 "content": "def transform(grid):
    """Complete the blank cells of the top panel using vertically aligned lower marks."""
    out = [row[:] for row in grid[:3]]
    for r in range(3):
        for c in range(6):
            if out[r][c] == 0:
                # The middle panel's color 4 has priority, then bottom-panel 8,
                # with panel 2 used only where neither higher layer marks it.
                for band, color in ((1, 4), (3, 8), (2, 2)):
                    if grid[3 * band + r][c] == color:
                        out[r][c] = color
                        break
    return out
